import React, { useState } from 'react';
import {
    View,
    Text,
    TouchableOpacity,
    Dimensions,
    ActivityIndicator
} from 'react-native';

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';

import api from '../../../services/api';

export function HamburgerMenu() {
    const {
        shoppingCartItem,
        selectedNumber,
        hamburgerMenuActive
    } = useContexState();

    const {
        setShoppingCartItem,
        setHamburgerMenuActive,
        setRegisterMenuActive,
    } = useContexState();

    const [LoadPopUpCart, setLoadPopUpCart] = useState(false);

    function LoadPopUp() {
        return <>
            <Text style={styles.textLoadPopUp}>Adicionando ao carrinho!</Text>
            <ActivityIndicator size={37} color='#fff' style={styles.ActivityIndicator} />
        </>
    }

    function AddToCart() {
        setLoadPopUpCart(true);
        api.post("registerBuy", {
            number: selectedNumber,
            name: 'Number added to cart',
            phone: '(__)_________',
        }).then((response) => {
            setLoadPopUpCart(false);
            setHamburgerMenuActive(false);
            setShoppingCartItem([...shoppingCartItem, Number(selectedNumber)]);
        });
    };

    function Menu() {
        return <>
            <TouchableOpacity
                onPress={() => {
                    AddToCart();
                    setRegisterMenuActive(true);
                }}
                style={styles.containerButtonPurchase} >
                <Text style={styles.textButtonPurchase}>Entrar</Text>
            </TouchableOpacity>

            <TouchableOpacity
                onPress={() => AddToCart()}
                style={styles.containerButtonAddCart} >
                <Text style={styles.textButtonAddCart}>Sobre</Text>
            </TouchableOpacity>
        </>
    }

    return !hamburgerMenuActive ?
        <>
            <TouchableOpacity onPress={() => {
                setHamburgerMenuActive(false);
            }} style={styles.containeMain} />


            <View style={{ width: '100%', alignItems: 'center', justifyContent: 'space-between', flexDirection: 'row', position: 'absolute' }}>



                <View style={styles.container} >

                    {LoadPopUpCart ? <LoadPopUp /> : <Menu />}
                </View>
            </View>

        </> : null
};
